namespace GitSweep.Core.Models;

/// <summary>
/// A branch deleted by GitSweep, kept in <c>.git/gitsweep/trash</c> so it can
/// be restored later. The <see cref="CommitSha"/> is captured immediately
/// before deletion; restoring recreates the branch at exactly that commit.
/// </summary>
/// <param name="Id">
/// Storage identifier. Generated by the trash service as a GUID in "N" format
/// and used as the on-disk file name, never derived from the branch name, so
/// a crafted branch name cannot influence the stored path.
/// </param>
/// <param name="BranchName">Short branch name that was deleted.</param>
/// <param name="CommitSha">Full hex SHA (40 or 64 chars) the branch pointed at.</param>
/// <param name="DeletedAtUtc">When the branch was deleted.</param>
/// <param name="BatchId">
/// Identifies one <c>clean</c> run: every branch deleted in the same run
/// shares the batch, so <c>undo</c> can restore exactly that run.
/// </param>
public sealed record TrashEntry(
    string Id,
    string BranchName,
    string CommitSha,
    DateTimeOffset DeletedAtUtc,
    Guid BatchId);
